/*
 * This file was generated by the Gradle 'init' task.
 *
 * This generated file contains a sample Java application project to get you started.
 * For more details on building Java & JVM projects, please refer to https://docs.gradle.org/9.2.1/userguide/building_java_projects.html in the Gradle documentation.
 */

plugins {
    // Apply the application plugin to add support for building a CLI application in Java.
    application

    // JavaFX support
    id("org.openjfx.javafxplugin") version "0.1.0"
}

repositories {
    // Use Maven Central for resolving dependencies.
    mavenCentral()
}

dependencies {
    // Use JUnit Jupiter for testing.
    testImplementation(libs.junit.jupiter)

    testRuntimeOnly("org.junit.platform:junit-platform-launcher")

    // This dependency is used by the application.
    implementation(libs.guava)
}

javafx {
    version = "21.0.2"
    modules = listOf(
        "javafx.controls",
        "javafx.graphics",
        "javafx.swing",
        "javafx.media"
    )
}

// Apply a specific Java toolchain to ease working on different environments.
java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(21)
    }
}

application {
    // Define the main class for the application.
    mainClass = "edu.hitsz.application.Main"
}

tasks.named<Test>("test") {
    // Use JUnit Platform for unit tests.
    useJUnitPlatform()
}

// 开发预览：以真实组件渲染静态效果图，不影响正式游戏或已提交包。
tasks.register<JavaExec>("effectsPreview") {
    dependsOn("testClasses")
    classpath = sourceSets["test"].runtimeClasspath
    mainClass = "edu.hitsz.application.EffectsPreview"
    javaLauncher = javaToolchains.launcherFor {
        languageVersion = JavaLanguageVersion.of(21)
    }
    args(rootProject.projectDir.resolve("../../output/effects-preview.png").absolutePath)
}

tasks.register<JavaExec>("experiencePreview") {
    dependsOn("testClasses")
    classpath = sourceSets["test"].runtimeClasspath
    mainClass = "edu.hitsz.application.ExperiencePreview"
    javaLauncher = javaToolchains.launcherFor { languageVersion = JavaLanguageVersion.of(21) }
    args(rootProject.projectDir.resolve("../../output/experience").absolutePath)
}
